# Bresenham-style path from cell a to b, sampled at BLOCK level: for each step along the major axis, block index = floor of point coordinate * 3/7.
def pts(a,b):
    r0,c0=a; r1,c1=b
    dy=r1-r0; dx=c1-c0
    res=[(r0,c0)]
    while True:
        res.append((r1,c1))
        break
    # implement properly
    return None
def path(a,b,mode='floor'):
    r0,c0=a; r1,c1=b
    dy=abs(r1-r0); dx=abs(c1-c0)
    signr=(r1>r0); signc=(c1>c0)
    e=0
    if dy>=dx:
        s=dy
        for _ in range(dy+1):
            yield (r0,c0)
            r0+=signr
            e+=dx
            if e>=s:
                c0+=signc
                e-=s
    else:
        s=dx
        for _ in range(dx+1):
            yield (r0,c0)
            c0+=signc
            e+=dy
            if e>=s:
                r0+=signr
                e-=s
def try_rule(pairs, scale=3/7, mode=np.floor):
    O=[[0]*3 for _ in range(3)]
    for (a,b) in pairs:
        for pt in path(a,b):
            rr=int(mode(pt[0]*scale)); cc=int(mode(pt[1]*scale))
            if 0<=rr<3 and 0<=cc<3: O[rr][cc]=8
    return O
