def f(g):
    cnt=Counter(v for r in g for v in r); bg=cnt.most_common(1)[0][0]
    h,w=len(g),len(g[0])
    cs=comps_of(g,bg)
    cand=[c for c in cs if len(c)>1]
    # choose comp whose bounding box has max (area*colorfulness) i.e., most cells
    best=max(cand,key=lambda c:(max(r for r,x in c)-min(r for r,x in c)+1)*(max(x for r,x in c)-min(x for r,x in c)+1))
    rs=[r for r,cx in best]; cls=[c for r,cx in best]
    r0,r1,c0,c1=min(rs),max(rs),min(cls),max(cls)
    T=[row[:] for row in g[r0:r1+1]]
    out=[row[:] for row in g]
    sing={cp[0] for cp in cs if len(cp)==1 and g[cp[0][0]][cp[0][1]]!=bg}
    for (r,c) in sorted(sing):
        for dr in range(-1,2):
            for dc in range(-1,2):
                rr,cc=r+dr,c+dc
                if 0<=rr<h and 0<=cc<w:
                    out[rr][cc]=T[dr+1][dc+1]
