def f(g):
    cnt=Counter(v for r in g for v in r); bg=cnt.most_common(1)[0][0]
    h,w=len(g),len(g[0])
    cs=comps_of(g,bg)
    cand=[c for c in cs if len(c)>1]
    def bbox_area(comp): return (max(r for r,x in comp)-min(r for r,x in comp)+1)*(max(x for r,x in comp)-min(x for r,x in comp)+1)
    best=max(cand,key=bbox_area)
    rs=[r for r,x in best]; cls_=[x for r,x in best]
    r0,r1,c0,c1=min(rs),max(rs),min(cls_),max(cls_)
    T=g[r0:r1+1][c0:c1+1]
    H,W=len(T),len(T[0])
    out=[row[:] for row in g]
    sing={cp[0] for cp in cs if len(cp)==1 and g[cp[0][0]][cp[0][1]]!=bg}
    # place tile center at stray; anchor: TL = (r - floor((H-1)/2), c - floor((W-1)/2))
    cr,cc = (H-1)//2,(W-1)//2
    for (r,c) in sorted(sing):
        tr,tc=r-cr,c-cc
        for dr in range(H):
            for dc in range(W):
                rr,ccc=tr+dr,tc+dc
                if 0<=rr<h and 0<=ccc<w:
                    out[rr][ccc]=T[dr][dc]
    return out
